    initialProcessStatus: [1, 2, 3, 4, 5, 201, 202, 210, 301, 401, 402, 403, 404, 405, 406, 407, 408, 409, 410, 411],

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        Ext.applyIf(
            cfg,
            {
                gridAutoLoad: true,
                archivedShowAllMenu: false,
                archivedOnlyMenu: false,
            }
        );

        cfg.archivedHideMenu = !(cfg.archivedShowAllMenu == true || cfg.archivedOnlyMenu == true);

        var gridAutoLoad = cfg.gridAutoLoad;
        cfg.gridAutoLoad = false;

        esocial.manager.EventGrid.superclass.constructor.call(this, cfg);
        this.gridAutoLoad = gridAutoLoad;
        this.canLoad = true;
        this.removeAllFilterProperty(this.gridAutoLoad);
    },

    __setFilterPropertyDefault: function (gridAutoLoad) {
        this.filterProcessStatus(undefined, false);

        var archived = false;
        if (this.archivedShowAllMenu == true)
            archived = null;
            if (this.archivedOnlyMenu == true)
            archived = true;
        this.filterArchiveds(archived, false);

        this.filterXmlInvalid(undefined, false);
        this.filterValids(undefined, false);
        this.filterAction(undefined, [], false);
        this.filterAcronym(undefined, [], false);

        this.runLoad(gridAutoLoad);
    },

    removeAllFilterProperty: function (load) {
        this.removeFilterProperty("xsd_schema_validated", 1010, false);
        this.removeFilterProperty("archived", 1020, false);
        this.removeFilterProperty("has_exclusion_cache", 1031, false);
        this.removeFilterProperty("is_invalid_cache", 1032, false);
        this.removeFilterProperty("action__in", 1040, false);
        this.removeFilterProperty("acronym__in", 1041, false);
        this.removeFilterProperty("competence_month", 800, false);
        this.removeFilterProperty("competence_year", 900, false);

        this.canLoad = false;

        this.getFilterStatus().forEach(function (el) {
            el.setChecked(true);
        });

        this.getActionMenuItems().forEach(function (el) {
            el.setChecked(false);
        });

        this.getFilterValidsMenu().setChecked(false);
        this.getFilterXmlInvalidMenu().setChecked(false);

        if (this.archivedHideMenu == true)
            this.getArchivedHideMenu().setChecked(true);
        if (this.archivedShowAllMenu == true)
            this.getArchivedShowAllMenu().setChecked(true);
        if (this.archivedOnlyMenu == true)
            this.getArchivedOnlyMenu().setChecked(true);

        this.canLoad = true;

        this.__setFilterPropertyDefault(load);
    },

    runLoad: function(gridAutoLoad){
        if (gridAutoLoad) {
            var store = this.getStore();
            store.load({});
        }
    },

