    getConfigActionsItems: function (cfg) {
        var menu = esocial.manager.EventGrid.superclass.getConfigActionsItems.call(this, cfg);

        menu['create-events'] = esocial.manager.EventGrid.createEventsToolBar(this);
        menu['custon-actions'] = esocial.manager.EventGrid.CustonActionsToolBar(this,cfg);
        menu['archive-events'] = esocial.manager.EventGrid.ArchiveEventsToolBar(this);

        if (cfg.maintenance) {
            menu['maintenance'] = esocial.manager.EventGrid.maintenanceToolBar(this);
        }
        menu['summary'] = {
            text: 'Sumário de eventos',
            iconCls: 'icon-esocial icon-reports',
            handler: function name(params) {
                Ext._create('esocial.manager.EventSummaryWindow', {
                    title: 'Sumário de eventos',
                    width: 600,
                    height: 600
                }).show();
            },
            scope: this,
        };
        menu['reload'] = {
            text: 'Atualizar',
            enableToggle: true,
            toggleHandler: function (item, pressed) {
                if (pressed === true) {
                    Ext.TaskMgr.start(this.reloadGridAuto());
                } else {
                    Ext.TaskMgr.stop(this.reloadGridAuto());
                }
            },
            pressed: false,
            scope: this
        };
        menu['employeExclude'] = {
            text: 'Remove servidor',
            iconCls: 'icon-16px icon-core icon-core-delete',
            tooltip: 'Remover servidor da geração de eventos cadastrais.',
            handler: function (item, pressed) {
                var selecteds = this.getSelectionModel().getSelections();
                if (selecteds.length > 0) {
                    var employees = [];
                    var i = 0, item;
                    while ((item = selecteds[i++])) {
                        employees.push(item.data.registry_employee);
                    }
                    this.executeAction(
                        "employee_exclude",
                        employees,
                        undefined,
                        "...",
                        undefined,
                        "esocial.manager.EventRestful"
                    );

                } else
                    Ext.MessageBox.show({
                        title: "Informação",
                        msg: "Primeiro selecione o(s) evento(s).",
                        buttons: Ext.MessageBox.OK,
                        icon: Ext.MessageBox.INFO,
                    });
            },
            pressed: false,
            scope: this
        };
        menu['changeProcessStatus'] = {
            text: 'Informar Sucesso',
            iconCls: 'icon-16px icon-core icon-core-update-manage',
            tooltip: 'Informar Sucesso do evento.',
            handler: function (item, pressed) {
                    var selRec = this.getSelectionModel().getSelected();
                    if (selRec)
                        this.executeAction(
                            "repport_success",
                            selRec.data.pk,
                            undefined,
                            "...",
                            undefined,
                            "esocial.manager.EventRestful"
                        );
                else
                    Ext.MessageBox.show({
                        title: "Informação",
                        msg: "Primeiro selecione o evento.",
                        buttons: Ext.MessageBox.OK,
                        icon: Ext.MessageBox.INFO,
                    });
            },
            pressed: false,
            scope: this
        };
        return menu;
    },

