                    if (!this.getSelectionModel().isSelected(index)) this.getSelectionModel().selectRow(index);
                    this.executeAction(
                        "validate",
                        {id: action._store.getAt(index).data.pk},
                        index,
                        "Consultando processamento do lote..."
                    );
